import itertools

def langford(n):
    # We need to place pairs for numbers 1..n
    # length = 2n
    length = 2 * n
    # We'll use backtracking
    seq = [0] * length  # 0 means empty

    # Order: try larger numbers first (common heuristic)
    def backtrack(pos):
        if pos == length:
            return True
        if seq[pos] != 0:
            return backtrack(pos + 1)
        # Try numbers from n down to 1
        for v in range(n, 0, -1):
            # Check if v already placed
            if v in seq:
                continue
            # Try placing first occurrence at pos
            second_pos = pos + v + 1
            if second_pos < length and seq[second_pos] == 0:
                seq[pos] = v
                seq[second_pos] = v
                if backtrack(pos + 1):
                    return True
                seq[pos] = 0
                seq[second_pos] = 0
        return False

    if backtrack(0):
        return seq
    return None

